std::unique_ptr<WindowPresenter> create_window_presenter(ID3D12Device* device, HWND window, bool hold_device) {
    ID3D12Device* real = rt::d3d12_xs::device_proxy_real_device(device);
    Device* d = Device::from<Device>(real ? real : device);
    if (device && !d)
        std::fprintf(stderr, "[rt] d3d12-metal: create_window_presenter: %p is neither the Xbox device proxy nor a "
                             "device of this layer; no presenter\n",
                     static_cast<void*>(device));
    if (!d || !window) return nullptr;
    void* layer = gta6rt_mac_window_metal_layer(reinterpret_cast<gta6rt_mac_window*>(window));
    if (!layer) {
        std::fprintf(stderr, "[rt] d3d12-metal: the window has no CAMetalLayer; no presenter\n");
        return nullptr;
    }
    auto& state = d->state();
    if (!state.present_queue) {
        state.present_queue = std::make_unique<leonida::MetalQueue>(*state.context, leonida::gpu::QueueType::direct,
                                                                    "present");
        if (!state.present_queue->ok()) return nullptr;
    }
    auto presenter = std::make_unique<leonida::MetalPresenter>(
        *state.context, *state.present_queue, layer, [window](std::uint32_t& w, std::uint32_t& h) {
            return gta6rt_mac_window_client_pixels(reinterpret_cast<gta6rt_mac_window*>(window), &w, &h) != 0;
        });
    if (!presenter->ok()) {
        std::fprintf(stderr, "[rt] d3d12-metal: no swapchain on the window's layer\n");
        return nullptr;
    }
    auto window_presenter = std::make_unique<WindowPresenter>(hold_device ? d->holder() : nullptr, std::move(presenter));
    window_presenter->set_window(window);
    return window_presenter;
}

HRESULT register_samplers(ID3D12Device* device, std::span<const leonida::gfx10::SamplerWords> samplers) {
    if (!device) return E_INVALIDARG;
    ID3D12Device* real = rt::d3d12_xs::device_proxy_real_device(device);
    Device* d = Device::from<Device>(real ? real : device);
    if (!d) return E_INVALIDARG;
    bool all = true;
    for (const leonida::gfx10::SamplerWords& words : samplers) all = d->bind_sampler(words) && all;
    return all ? S_OK : E_FAIL;
}

